229:         var requestId=Guid.NewGuid().ToString(); var user=User(); var now=Now; var day=BusinessDay(now);
230:         if(user.Role==Role.Viewer) return Result(Outcome.Forbidden,"E-COM-002","保存権限がありません。",requestId);
231:         NormalizedStudent student; string? reason;
232:         try {
233:             student=StudentNormalizer.Normalize(request.Draft,day);
234:             reason=StudentNormalizer.Text(request.Reason,60,60,"Reason",multiline:true);
235:             if(request.StudentId is <=0 || request.ExpectedVersion is <=0 || (request.StudentId is null)!=(request.ExpectedVersion is null)) throw new ArgumentException("E-COM-003: 学生ID/版が不正です。");
236:             if(request.SchoolYear is <1900 or >9998) throw new ArgumentException("E-DATE-003: 年度が不正です。");
237:             request=request with { GradeCode=StudentNormalizer.Code(request.GradeCode,2,"GradeCode",false) };
238:         } catch(InputValidationException e) { return new(Outcome.ValidationFailed,null,null,e.Errors,RequestId:requestId); }
239:         catch(ArgumentException e) { return new(Outcome.ValidationFailed,null,null,[StudentNormalizer.ArgumentError("Save",e)],RequestId:requestId); }
240:         var writeStarted=false; var commitAttempted=false; var completed=false; var unknown=false; Confirmation? claimed=null;
241:         await using var connection=await Open(ct);
242:         await using var tx=(SqlTransaction)await connection.BeginTransactionAsync(IsolationLevel.ReadCommitted,ct);
243:         try {
244:             await Gate(connection,tx,ct);
245:             Dictionary<string,object?>? previous=null; long? previousVersion=null;
246:             if(request.StudentId is { } existing) {
247:                 await using var load=Command(connection,tx,"SELECT * FROM dbo.m_student WHERE student_id=@id AND is_deleted=0");
248:                 Param(load,"@id",SqlDbType.BigInt,existing);
249:                 await using var reader=await load.ExecuteReaderAsync(ct);
250:                 if(!await reader.ReadAsync(ct)) return Result(Outcome.NotFound,"E-STU-103","対象学生が存在しません。",requestId);
251:                 previousVersion=Long(reader,"row_version");
252:                 if(previousVersion!=request.ExpectedVersion) return Result(Outcome.Conflict,"E-STU-105","他の利用者が変更しています。再読込してください。",requestId);
253:                 previous=Columns.Keys.ToDictionary(key=>key,key=>reader.IsDBNull(reader.GetOrdinal(key))?null:reader[key]);
254:                 if((string)previous["student_no"]! != student.Text("student_no")) return Result(Outcome.ValidationFailed,"E-STU-104","学籍番号は変更できません。",requestId);
255:                 if((string)previous["enrollment_status_code"]! is "03" or "04" && !Equals(previous["enrollment_status_code"],student.Values["enrollment_status_code"])) {
256:                     if(user.Role!=Role.Administrator) return Result(Outcome.Forbidden,"E-COM-002","終了区分の訂正は管理者権限が必要です。",requestId);
257:                     if(reason is null) return Result(Outcome.ValidationFailed,"E-STU-106","終了区分の訂正理由を入力してください。",requestId);
258:                 }
259:             }
260:             await CheckRules(connection,tx,student,previous,request,day,ct);
261:             var changed=student.Values.Where(pair=>previous is null || !EqualValue(pair.Value,previous[pair.Key])).Select(pair=>pair.Key).ToArray();
262:             if(changed.Length==0) { await tx.RollbackAsync(ct); return new(Outcome.NoChange,request.StudentId,previousVersion,[],RequestId:requestId); }
263:             if(previousVersion==long.MaxValue) return Result(Outcome.Conflict,"E-STU-105","更新管理番号が上限に到達しました。",requestId);
264:             await using(var number=Command(connection,tx,"SELECT COUNT_BIG(*) FROM dbo.m_student WHERE student_no=@no AND (@id IS NULL OR student_id<>@id)")) {
265:                 Param(number,"@no",SqlDbType.VarChar,student.Text("student_no"),15); Param(number,"@id",SqlDbType.BigInt,request.StudentId);
266:                 if((long)(await number.ExecuteScalarAsync(ct))!>0) return Result(Outcome.ValidationFailed,"E-STU-101","学籍番号は使用済みです。",requestId);
267:             }
268:             var candidates=new List<StudentRow>();
269:             await using(var duplicate=Command(connection,tx,RowSelect+" WHERE s.is_deleted=0 AND (@id IS NULL OR s.student_id<>@id) AND s.birth_date=@birth AND (s.name_key=@name OR s.kana_key=@kana) ORDER BY s.student_id")) {
270:                 Param(duplicate,"@id",SqlDbType.BigInt,request.StudentId); Param(duplicate,"@birth",SqlDbType.Date,student.Date("birth_date"));
271:                 Param(duplicate,"@name",SqlDbType.NVarChar,student.Text("name_key"),320); Param(duplicate,"@kana",SqlDbType.NVarChar,student.Text("kana_key"),36);
272:                 await using var reader=await duplicate.ExecuteReaderAsync(ct); while(await reader.ReadAsync(ct)) candidates.Add(Row(reader));
273:             }
274:             var payload=HashPayload(student); var candidateHash=HashCandidates(candidates);
275:             var confirmationValid=false;
276:             if(request.ConfirmationToken is { } supplied) {
277:                 if(_webTokens) {
278:                     if(WebConfirmations.TryGetValue(supplied,out var value) && value.Owner.Principal==user.Principal && value.Owner.SessionId==user.SessionId && value.Id==request.StudentId && value.Version==request.ExpectedVersion && value.Expires>now && CryptographicOperations.FixedTimeEquals(value.Payload,payload) && CryptographicOperations.FixedTimeEquals(value.Candidates,candidateHash) && Interlocked.CompareExchange(ref value.Busy,1,0)==0) { claimed=value; confirmationValid=true; }
279:                 } else if(Guid.TryParse(supplied,out var token)) {
280:                     await using var check=Command(connection,tx,"SELECT payload_hash,candidate_hash FROM dbo.t_confirmation WITH (UPDLOCK) WHERE token=@token AND principal=@actor AND session_id=@session AND ((target_id IS NULL AND @id IS NULL) OR target_id=@id) AND ((expected_version IS NULL AND @version IS NULL) OR expected_version=@version) AND expires_at>@now AND consumed=0");
281:                     Param(check,"@token",SqlDbType.UniqueIdentifier,token); Param(check,"@actor",SqlDbType.NVarChar,user.Principal,128); Param(check,"@session",SqlDbType.UniqueIdentifier,Guid.Parse(user.SessionId)); Param(check,"@id",SqlDbType.BigInt,request.StudentId); Param(check,"@version",SqlDbType.BigInt,request.ExpectedVersion); Param(check,"@now",SqlDbType.DateTimeOffset,now);
282:                     await using var reader=await check.ExecuteReaderAsync(ct);
283:                     confirmationValid=await reader.ReadAsync(ct) && CryptographicOperations.FixedTimeEquals((byte[])reader[0],payload) && CryptographicOperations.FixedTimeEquals((byte[])reader[1],candidateHash);
284:                 }
285:             }
286:             if(confirmationValid && reason is null) return Result(Outcome.ValidationFailed,"E-STU-107","重複登録を続ける理由を入力してください。",requestId);
287:             if((candidates.Count>0 || request.ConfirmationToken is not null) && !confirmationValid) {
288:                 await tx.RollbackAsync(ct);
289:                 var token=await IssueConfirmation(connection,user,request,payload,candidateHash,now,ct);
290:                 return new(Outcome.ConfirmationRequired,request.StudentId,previousVersion,[],token,candidates.Count,candidates.Take(20).ToArray(),requestId);
291:             }
292:             long id; var version=(previousVersion??0)+1;
293:             var insert=request.StudentId is null;
294:             var writeColumns=student.Values.Keys.Where(key=>insert || key!="student_no").ToArray();
295:             var sql=insert
296:                 ? "DECLARE @changed TABLE(student_id bigint); INSERT INTO dbo.m_student ("+string.Join(',',writeColumns)+",gender_category,prefecture_category,enrollment_category,is_deleted,created_at,created_by,updated_at,updated_by,row_version) OUTPUT INSERTED.student_id INTO @changed VALUES ("+string.Join(',',writeColumns.Select(key=>"@"+key))+",'GENDER','PREFECTURE','ENROLLMENT_STATUS',0,@now,@actor,@now,@actor,1); SELECT student_id FROM @changed;"
297:                 : "DECLARE @changed TABLE(student_id bigint); UPDATE dbo.m_student SET "+string.Join(',',writeColumns.Select(key=>key+"=@"+key))+",updated_at=@now,updated_by=@actor,row_version=row_version+1 OUTPUT INSERTED.student_id INTO @changed WHERE student_id=@id AND row_version=@version AND is_deleted=0; SELECT student_id FROM @changed;";
298:             await using(var save=Command(connection,tx,sql)) {
299:                 foreach(var key in writeColumns) Param(save,"@"+key,Columns[key].Type,student.Values[key],Columns[key].Size);
300:                 Param(save,"@now",SqlDbType.DateTimeOffset,now); Param(save,"@actor",SqlDbType.NVarChar,user.Principal,128);
301:                 if(!insert) { Param(save,"@id",SqlDbType.BigInt,request.StudentId); Param(save,"@version",SqlDbType.BigInt,request.ExpectedVersion); }
302:                 writeStarted=true; var saved=await save.ExecuteScalarAsync(ct);
303:                 if(saved is null || saved is DBNull) throw new DBConcurrencyException();
304:                 id=(long)saved;
305:             }
306:             var auditChanged=insert ? writeColumns.Concat(new[]{"gender_category","prefecture_category","enrollment_category","is_deleted","created_at","created_by","updated_at","updated_by","row_version"}).ToArray() : changed.Concat(new[]{"updated_at","updated_by","row_version"}).ToArray();
307:             await Audit(connection,tx,id,insert?"CREATE":"UPDATE",previousVersion,version,auditChanged,user.Principal,now,reason,candidates.Count>0,Guid.Parse(requestId),ct);
308:             if(confirmationValid && !_webTokens) {
309:                 await using var consume=Command(connection,tx,"UPDATE dbo.t_confirmation SET consumed=1 WHERE token=@token AND consumed=0");
310:                 Param(consume,"@token",SqlDbType.UniqueIdentifier,Guid.Parse(request.ConfirmationToken!));
311:                 if(await consume.ExecuteNonQueryAsync(ct)!=1) throw new DBConcurrencyException();
312:             }
313:             commitAttempted=true; await tx.CommitAsync(ct); completed=true;
314:             if(request.ConfirmationToken is { } consumed) WebConfirmations.TryRemove(consumed,out _);
315:             return new(Outcome.Saved,id,version,[],RequestId:requestId);
316:         } catch(InputValidationException e) { await Rollback(tx); return new(Outcome.ValidationFailed,null,null,e.Errors,RequestId:requestId); }
317:         catch(SqlException e) when(e.Number is 2601 or 2627) { await Rollback(tx); return Result(Outcome.ValidationFailed,"E-STU-101","学籍番号は使用済みです。",requestId); }
318:         catch(DBConcurrencyException) { await Rollback(tx); return Result(Outcome.Conflict,"E-STU-105","他の利用者が変更しています。",requestId); }
319:         catch(Exception e) when(e is SqlException or InvalidOperationException or OperationCanceledException) {
320:             var rolledBack=await Rollback(tx); unknown=writeStarted&&(commitAttempted||!rolledBack);
321:             if(unknown && request.ConfirmationToken is { } invalid) WebConfirmations.TryRemove(invalid,out _);
322:             return Result(unknown?Outcome.Unknown:Outcome.SystemError,"E-COM-004",unknown?"保存結果を確認できません。再保存の前に検索で確認してください。":"処理に失敗しました。受付番号："+requestId,requestId);
323:         } finally { if(claimed is not null && !completed && !unknown) Interlocked.Exchange(ref claimed.Busy,0); }

