10: <label>住所1 ※必須<input asp-for="Input.AddressLine1" id="REG-009" maxlength="90" required><small>45文字以内</small></label><label>住所2<input asp-for="Input.AddressLine2" id="REG-010" maxlength="90"></label><label>本人電話<input asp-for="Input.PhoneNumber" id="REG-011" maxlength="40"><small>原入力20、正規化後16文字</small></label><label>本人メール<input asp-for="Input.EmailAddress" id="REG-012" maxlength="120"></label>
11: <label>入学日 ※必須<input asp-for="Input.AdmissionDate" id="REG-013" type="date" required></label><label>在籍区分 ※必須<select asp-for="Input.EnrollmentStatusCode" id="REG-014" required>@foreach(var c in codes.Where(c=>c.CategoryId=="ENROLLMENT_STATUS")){bool selectable=c.IsActive&&c.ValidFrom<=today&&(c.ValidTo is null||today<=c.ValidTo)||Model.Detail?.Draft.EnrollmentStatusCode==c.CodeValue;<option value="@c.CodeValue" disabled="@(!selectable)">@c.CodeName</option>}</select></label><label>卒業・退学日<input asp-for="Input.EnrollmentEndDate" id="REG-015" type="date"></label>
12: <label>年度<select asp-for="Input.SchoolYear" id="REG-016"><option value="">未指定</option>@foreach(var y in Model.Lookups.Classes.Select(c=>c.SchoolYear).Concat(input.SchoolYear.HasValue?[input.SchoolYear.Value]:[]).Distinct().OrderDescending()){<option value="@y">@y</option>}</select></label><label>学年<select asp-for="Input.GradeCode" id="REG-017"><option value="">すべて</option>@foreach(var c in codes.Where(c=>c.CategoryId=="GRADE")){<option value="@c.CodeValue">@c.CodeName</option>}</select></label><label>クラス<select asp-for="Input.ClassId" id="REG-018"><option value="">未所属</option>@foreach(var c in Model.Lookups.Classes){bool active=c.IsActive&&c.ValidFrom<=today&&today<=c.ValidTo;bool terminal=input.EnrollmentStatusCode is "03" or "04";bool overlap=DateOnly.TryParse(input.AdmissionDate,out var a)&&DateOnly.TryParse(input.EnrollmentEndDate,out var e)&&c.ValidFrom<=e&&a<=c.ValidTo;bool keep=Model.Detail?.Draft.ClassId==c.ClassId;bool selectable=keep||(terminal?overlap:active);<option value="@c.ClassId" data-year="@c.SchoolYear" data-grade="@c.GradeCode" disabled="@(!selectable)">@c.SchoolYear @c.GradeCode @c.ClassCode @c.ClassName @(!c.IsActive?"（停止）":!active?"（期間外）":"")</option>}</select><small>人数 @(cls?.Occupied.ToString()??"－")／定員 @(cls?.Capacity.ToString()??"制限なし")（参考）</small></label>
13: <label>緊急連絡先氏名<input asp-for="Input.EmergencyContactName" id="REG-020" maxlength="16"></label><label>緊急連絡先続柄<select asp-for="Input.RelationshipCode" id="REG-021"><option value="">未選択</option>@foreach(var c in codes.Where(c=>c.CategoryId=="RELATIONSHIP")){bool selectable=c.IsActive&&c.ValidFrom<=today&&(c.ValidTo is null||today<=c.ValidTo)||Model.Detail?.Draft.RelationshipCode==c.CodeValue;<option value="@c.CodeValue" disabled="@(!selectable)">@c.CodeName</option>}</select></label><label>緊急連絡先電話<input asp-for="Input.EmergencyPhoneNumber" id="REG-022" maxlength="40"></label><label class="full">備考<textarea asp-for="Input.Remarks" id="REG-023" maxlength="240"></textarea></label><label class="full">確認・変更理由<textarea asp-for="Input.OperationReason" id="REG-024" maxlength="120"></textarea></label></div><p>本人電話・メール・緊急電話のいずれか1つ以上。緊急連絡先は3項目すべて入力してください。</p>
14: @if(Model.Result?.Outcome==Outcome.ConfirmationRequired){<section role="dialog" aria-labelledby="duplicate-title" class="warning"><h2 id="duplicate-title">同一人物候補の確認</h2><p>全 @Model.Result.CandidateCount 件、最大20件表示</p><table><thead><tr><th>学籍番号</th><th>氏名</th><th>和暦生年月日</th><th>クラス</th></tr></thead><tbody>@foreach(var c in (Model.Result.Candidates??[]).Take(20)){<tr><td>@c.StudentNo</td><td>@c.StudentName</td><td>@c.BirthDateWareki</td><td>@c.ClassName</td></tr>}</tbody></table><p>別人と確認した場合は、確認理由を入力して続行してください。</p><button type="button" data-cancel-duplicate autofocus>確認取消</button><button type="submit" data-confirm="別人として保存しますか。">別人と確認して続行</button></section>}
